// Merge FHIR Observation values into the webhook payload (lab values for the model)

// Output of "PPH: Fetch Observations" can be a parsed bundle, or a raw JSON string in .data
const raw = $input.first().json ?? {};
let bundle = raw;
if (typeof raw.data === 'string') {
  try { bundle = JSON.parse(raw.data); } catch (e) { bundle = {}; }
} else if (raw.data && typeof raw.data === 'object') {
  bundle = raw.data;
}

// Original webhook payload (patientId, fhirBase) sent by the dashboard
const webhook = $('POST /my-pph-model-run').first().json ?? {};
const payload = webhook.body ?? webhook;

// LOINC code -> lab name
const loincMap = {
  '20570-8': 'hematocrit',
  '777-3':   'platelet',
  '26449-9': 'platelet',
  '32623-1': 'platelet',
  '29463-7': 'maternal_weight',
  '8867-4':  'pulse',
  '26464-8': 'wbc',
};

// Keep only the most recent reading of each lab
const latest = {};
for (const e of (bundle.entry ?? [])) {
  const obs = e.resource ?? {};
  const lab = loincMap[obs.code?.coding?.[0]?.code];
  const val = obs.valueQuantity?.value;
  if (!lab || val == null) continue;
  const t = new Date(obs.effectiveDateTime || obs.issued || 0).getTime();
  if (!latest[lab] || t > latest[lab].t) latest[lab] = { val, t };
}

const merged = { ...payload };
for (const [lab, { val }] of Object.entries(latest)) merged[lab] = val;

return [{ json: merged }];

// ── MY PPH MODEL: RISK SCORER ────────────────────────────────────────────────
const errorCard = (title, msg) => `<div style="font-family:system-ui,sans-serif;padding:20px">
  <div style="background:#fef2f2;border:2px solid #dc2626;border-radius:10px;padding:20px">
    <div style="font-weight:700;font-size:16px;color:#991b1b;margin-bottom:6px">${title}</div>
    <div style="color:#7f1d1d;font-size:13px;line-height:1.6">${msg}</div>
  </div>
</div>`;

try {
  const input     = $input.first().json ?? {};
  const patientId = input.patientId ?? '';
  const fhirBase  = (input.fhirBase || 'http://r4:8080/hapi-fhir-jpaserver/fhir').replace('localhost', 'host.docker.internal');

  if (!patientId) {
    return [{ json: { html: errorCard('No patient selected', 'Select a patient in the dashboard, then click the button again.') } }];
  }

  // Fetch the patient record to read the risk-factor extensions
  const patient = await this.helpers.request({ method: 'GET', url: `${fhirBase}/Patient/${patientId}`, json: true });
  const extMap = {};
  for (const e of (patient.extension ?? [])) {
    const key = e.url?.split('/').pop();
    extMap[key] = e.valueBoolean ?? e.valueString ?? e.valueInteger ?? e.valueDecimal ?? null;
  }

  if (extMap['pph-data'] !== true) {
    return [{ json: { html: errorCard('Not a PPH study patient', 'This patient has no PPH study data. Select a patient whose ID starts with <code>pph-</code>.') } }];
  }

  // ============================================================
  // STEP 2: YOUR MODEL. This is the only block you (or the AI) change.
  // Replace `const MODEL = null;` with your model.pkl values, in this format:
  //
  // const MODEL = {
  //   intercept: <number>,
  //   numeric: {                       // every numeric predictor, in any order
  //     prior_pph:  { coef: <number>, fill: <median>, source: 'ext:prior-pph' },
  //     hematocrit: { coef: <number>, fill: <median>, source: 'lab:hematocrit' },
  //     calcium:    { coef: <number>, fill: <median>, source: null },   // not in the chart
  //     ...
  //   },
  //   categorical: {                   // every one-hot encoded predictor
  //     delivery_type_label: {
  //       source: 'ext:delivery-type', fill: '<most frequent value>',
  //       coef: { '<dropped category>': 0, '<category>': <number>, ... },
  //     },
  //     ...
  //   },
  //   alertThreshold: 0.03,            // above this = High (alert)
  // };
  //
  // Where each predictor can come from (source):
  //   'ext:<key>' = patient record extension. Available keys:
  //       prior-pph, placenta-accreta, general-anesthesia, multiple-gestation,
  //       placenta-previa, induction-of-labor, augmentation, labor-length,
  //       hypertensive-disorder, maternal-obesity, cesarean-prior, diabetes,
  //       chorioamnionitis, polyhydramnios, fetal-macrosomia,
  //       delivery-type ('Vaginal', 'Cesarean', 'Instrumented vaginal')
  //   'lab:<key>' = most recent lab value. Available keys:
  //       hematocrit, platelet, maternal_weight, pulse, wbc
  //   null        = not in the chart, the card uses `fill` (the pipeline's own value)
  // A value missing for one patient also falls back to `fill`, like the pipeline does.
  // Category text is matched without caring about capitalization.
  // ============================================================
  const MODEL = {
    intercept: 0.6164088420636828,
    numeric: {
      prior_pph: { coef: 2.4360987194565347, fill: 0.0, source: 'ext:prior-pph' },
      placenta_accreta: { coef: 2.493923629659058, fill: 0.0, source: 'ext:placenta-accreta' },
      general_anesthesia: { coef: 1.5276528917015002, fill: 0.0, source: 'ext:general-anesthesia' },
      multiple_gestation: { coef: 1.49448180558098, fill: 0.0, source: 'ext:multiple-gestation' },
      placenta_previa: { coef: 1.0331186378169854, fill: 0.0, source: 'ext:placenta-previa' },
      induction_of_labor: { coef: 0.5174756274680327, fill: 0.0, source: 'ext:induction-of-labor' },
      augmentation: { coef: 0.5167043101352291, fill: 0.0, source: 'ext:augmentation' },
      labor_length: { coef: 0.6820149851159096, fill: 0.0, source: 'ext:labor-length' },
      hypertensive: { coef: 0.4351352677818229, fill: 0.0, source: 'ext:hypertensive-disorder' },
      prom: { coef: -0.978449646624105, fill: 0.0, source: null },
      nifedipine: { coef: 0.6555600516442738, fill: 0.0, source: null },
      terbutaline: { coef: 0.6045103040897166, fill: 0.0, source: null },
      placental_abruption: { coef: 0.6543639457899865, fill: 0.0, source: null },
      hematocrit: { coef: -0.13725585527055392, fill: 35.5, source: 'lab:hematocrit' },
      platelet: { coef: -0.0022503817135468797, fill: 230.2, source: 'lab:platelet' },
      maternal_weight: { coef: -0.009595479990004173, fill: 81.85, source: 'lab:maternal_weight' },
      pulse1: { coef: 0.01089718976375829, fill: 88.0, source: 'lab:pulse' },
      wbc: { coef: 0.04168272505902857, fill: 11.0, source: 'lab:wbc' },
      calcium: { coef: 0.16447268235407106, fill: 8.8, source: null }
    },
    categorical: {
      delivery_type_label: {
        source: 'ext:delivery-type', fill: 'vaginal',
        coef: { 'Cesarean': 0.0, 'instrumented vaginal': -0.33049071811346886, 'vaginal': -1.4171235297546863 }
      },
      fetal_size_label: {
        source: null, fill: 'normal',
        coef: { 'large': 0.0, 'normal': -0.6233695868014818, 'small': -1.4069626460024596 }
      }
    },
    alertThreshold: 0.03,
  };
  // ================= END OF STEP 2 =================

  if (MODEL === null) {
    return [{ json: { html: errorCard('STEP 2 is still empty', 'The workflow runs, but your model is not wired in yet. Fill in the MODEL block inside <b>PPH: Compute Risk Score</b>, save, and run again.') } }];
  }

  // ── Scoring: reproduces the pipeline (fill missing values, one-hot encode, logistic regression)
  const read  = (src) => { if (!src) return null; const [kind, key] = src.split(':'); return kind === 'ext' ? extMap[key] : kind === 'lab' ? input[key] : null; };
  const toNum = (v) => v === true ? 1 : v === false ? 0 : (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
  const pretty = (k) => k.replace(/_label$/, '').replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());

  let z = MODEL.intercept;
  const rows = [];
  for (const [name, f] of Object.entries(MODEL.numeric)) {
    const v = toNum(read(f.source));
    const used = v ?? f.fill;
    z += f.coef * used;
    rows.push({ label: pretty(name), shown: v === null ? `${f.fill} (filled)` : String(+used.toFixed(2)), contrib: f.coef * (used - f.fill), filled: v === null });
  }
  for (const [name, f] of Object.entries(MODEL.categorical)) {
    const rawV = read(f.source);
    const cats = Object.keys(f.coef);
    let cat, w;
    if (rawV === null || rawV === undefined || rawV === '') { cat = f.fill; w = f.coef[f.fill] ?? 0; }
    else {
      cat = cats.find(c => c.toLowerCase() === String(rawV).trim().toLowerCase());
      w = cat === undefined ? 0 : f.coef[cat];          // unknown category = baseline, like handle_unknown='ignore'
      if (cat === undefined) cat = String(rawV);
    }
    z += w;
    rows.push({ label: pretty(name), shown: (rawV === null || rawV === undefined || rawV === '') ? `${cat} (filled)` : cat, contrib: w - (f.coef[f.fill] ?? 0), filled: rawV === null || rawV === undefined || rawV === '' });
  }

  const prob      = 1 / (1 + Math.exp(-z));
  const probPct   = (prob * 100).toFixed(1);
  const alert     = prob > MODEL.alertThreshold;
  const tier      = alert ? 'High (alert)' : 'Low';
  const tierColor = alert ? '#dc2626' : '#16a34a';
  const tierBg    = alert ? '#fef2f2' : '#f0fdf4';
  const outcome   = extMap['pph-outcome'];
  const outColor  = outcome === 1 ? '#dc2626' : '#16a34a';
  const outText   = outcome === 1 ? 'PPH occurred' : 'No PPH';

  rows.sort((a, b) => Math.abs(b.contrib) - Math.abs(a.contrib));
  const rowHtml = rows.map(r => {
    const dir  = r.contrib > 0 ? '#dc2626' : r.contrib < 0 ? '#16a34a' : '#9ca3af';
    const sign = r.contrib > 0 ? '▲' : r.contrib < 0 ? '▼' : '·';
    const barW = Math.min(100, Math.abs(r.contrib) * 60).toFixed(0);
    return `<tr style="border-bottom:1px solid #f3f4f6;opacity:${r.filled ? '0.45' : '1'}">
      <td style="padding:5px 10px;font-size:13px">${r.label}</td>
      <td style="padding:5px 10px;text-align:center;font-size:12px;color:#4f46e5">${r.shown}</td>
      <td style="padding:5px 10px"><div style="display:flex;align-items:center;gap:6px">
        <div style="width:70px;background:#f3f4f6;border-radius:3px;height:7px;flex-shrink:0"><div style="width:${barW}%;background:${dir};height:7px;border-radius:3px"></div></div>
        <span style="font-size:11px;color:${dir};font-weight:700">${sign} ${r.contrib.toFixed(3)}</span>
      </div></td>
    </tr>`;
  }).join('');

  const html = `
<div style="font-family:system-ui,sans-serif" data-prob="${prob}">
  <div style="background:${tierBg};border:2px solid ${tierColor};border-radius:12px;padding:18px 22px;margin-bottom:16px;display:flex;align-items:center;gap:18px">
    <div style="flex:1">
      <div style="font-size:26px;font-weight:800;color:${tierColor}">${tier}</div>
      <div style="font-size:16px;font-weight:600;color:${tierColor};margin-top:2px">${probPct}% predicted PPH probability</div>
      <div style="font-size:11px;color:#6b7280;margin-top:6px">Scored by my Week 4 model · alert above ${(MODEL.alertThreshold * 100).toFixed(0)}%</div>
    </div>
    <div style="text-align:center;background:#fff;border-radius:8px;padding:10px 14px;border:1px solid #e5e7eb">
      <div style="font-size:28px;font-weight:800;color:${tierColor}">${probPct}%</div>
      <div style="font-size:11px;color:#6b7280">PPH Prob</div>
    </div>
  </div>
  <div style="background:#fff;border:1px solid ${outColor}40;border-radius:8px;padding:12px 16px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center">
    <div style="font-weight:700;font-size:13px;color:${outColor}">Actual study outcome</div>
    <div style="font-size:15px;font-weight:700;color:${outColor}">${outText}</div>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:14px">
    <div style="font-weight:700;font-size:13px;margin-bottom:10px">What moved the score (compared with a typical patient)</div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f9fafb">
        <th style="padding:7px 10px;text-align:left;font-size:11px;color:#6b7280">PREDICTOR</th>
        <th style="padding:7px 10px;text-align:center;font-size:11px;color:#6b7280">VALUE</th>
        <th style="padding:7px 10px;text-align:left;font-size:11px;color:#6b7280">CONTRIBUTION</th>
      </tr></thead>
      <tbody>${rowHtml}</tbody>
    </table>
  </div>
  <div style="font-size:11px;color:#9ca3af;margin-top:8px">Educational use only · Grayed = not in the chart, filled with the pipeline's own value</div>
</div>`;

  return [{ json: { html } }];

} catch (err) {
  return [{ json: { html: errorCard('The scorer hit an error', `${err.message}<br><br>Open n8n's Executions tab for details.`) } }];
}
